import {advanceWork,createWork,trackOperationalChanges} from './workflow.mjs';
import {workflowView} from './workflow-ui.mjs';
import {projects,initialState,metrics,totals,eligibility,assign,addQA} from './model.mjs';
import {loadWorkspace,saveWorkspace,createBackup,parseBackup,MAX_BACKUP_BYTES,csvCell} from './workspace.mjs';
const $=s=>document.querySelector(s),money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n),pct=n=>n.toFixed(1)+'%';
const safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let selectedWork='WORK-001',historyProject='all',historyActor='';
let state=initialState(),page='Overview',filter='all',search='',workerStatus='all',selected='P01',drawer=false;
let storage;
try { storage=window.localStorage; } catch { storage={getItem(){throw Error('Unavailable')},setItem(){throw Error('Unavailable')}}; }
const loaded=loadWorkspace(storage); state=loaded.state;
let storageProblem=loaded.problem, damagedRaw=loaded.raw, pendingRestore=null, confirmReset=false;
function persist(){
  if(damagedRaw!==null) return false;
  try{state=saveWorkspace(storage,state);storageProblem=null;return true;}
  catch{storageProblem='Changes are kept in this session only. Browser storage is unavailable or full. Download a backup before closing.';return false;}
}
function downloadText(text,filename,type='application/json'){
  const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');
  a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
}
function backupWorkspace(){downloadText(createBackup(state),'FieldOps-Workspace-'+new Date().toISOString().slice(0,10)+'.json');toast('Workspace backup downloaded. Keep this file to restore your decisions.');}
function workspaceControls(){return `<section class="card workspace-tools"><div class="card-head"><div><h2>Workspace backup & recovery</h2><p>Keep a copy of your staffing decisions, QA allocations and incident history.</p></div><span class="badge gray">Browser workspace</span></div><div class="panel-body"><p>Changes are stored on this device. A JSON backup lets you restore this demo scenario in another browser. It does not connect a team or import real staff records.</p><div class="actions"><button class="btn primary" id="backup-workspace">Download workspace backup</button><button class="btn" id="choose-restore">Restore a backup</button><input type="file" id="restore-file" accept=".json,application/json" hidden></div><p id="restore-error" role="alert" class="recovery-error"></p>${pendingRestore?`<div class="callout"><h3>Review backup before restoring</h3><p>Exported ${safe(new Date(pendingRestore.exportedAt).toLocaleString('en-US',{timeZone:'UTC'}))} UTC · ${pendingRestore.state.workers.filter(w=>w.status==='Collecting').length} active workers · ${pendingRestore.state.audit.length} history entries.</p><p>This replaces the current scenario. Download your current backup first if you want to keep it. Restored history is editable demo data, not a verified business audit.</p><div class="actions"><button class="btn primary" id="confirm-restore">Replace workspace with this backup</button><button class="btn" id="cancel-restore">Cancel restore</button></div></div>`:''}</div></section>`;}
function recoveryBanner(){return storageProblem?`<section class="recovery-banner" role="alert"><b>Workspace storage needs attention</b><p>${safe(storageProblem)}</p>${damagedRaw!==null?'<p>Scenario changes are temporary until you explicitly replace the saved workspace.</p><div class="actions"><button class="btn" id="download-damaged">Download preserved saved data</button><button class="btn" id="replace-damaged">Replace saved data with current scenario</button></div>':''}</section>`:'';}
function resetControls(){return confirmReset?`<div class="callout"><b>Reset this scenario?</b><p>This resets staffing, QA, connectivity stress and incident statuses. Work items and recorded workflow history are retained. Download a backup first to keep them.</p><div class="actions"><button class="btn" id="backup-workspace">Download workspace backup</button><button class="btn primary" id="confirm-reset">Confirm reset to baseline</button><button class="btn" id="cancel-reset">Keep current scenario</button></div></div>`:'<button class="btn" id="reset">Reset all demo changes</button>';}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',3500);}
const icons={Workflows:'<path d="M4 4h6v6H4ZM14 14h6v6h-6ZM7 10v7h7M14 4h6M17 1v6"/>',Overview:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',Workforce:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6M18 15a5 5 0 0 1 3 5"/>',Quality:'<path d="M12 3 3 7v6c0 5 9 9 9 9s9-4 9-9V7Z"/><path d="m8 12 3 3 5-6"/>',Incidents:'<path d="m12 3 10 18H2ZM12 9v5M12 17v1"/>',Scenarios:'<path d="M4 6h16M4 12h16M4 18h16"/><circle cx="8" cy="6" r="2"/><circle cx="16" cy="12" r="2"/><circle cx="10" cy="18" r="2"/>',Reports:'<path d="M6 3h9l4 4v14H6ZM14 3v5h5M9 12h7M9 16h7"/>'};
function badge(t,c='green'){return `<span class="badge ${c}"><span class="status-dot"></span>${t}</span>`;}
function overview(){const ms=totals(state),accepted=ms.reduce((n,m)=>n+m.accepted,0),target=ms.reduce((n,m)=>n+m.target,0),active=state.workers.filter(w=>w.status==='Collecting').length,first=ms.reduce((n,m)=>n+m.firstPass,0)/ms.reduce((n,m)=>n+m.firstReviews,0),risk=ms.filter(m=>m.shortfall).length;return `
<div class="banner"><span>◈</span><div><b>Your staffing and delivery picture, in one place.</b> ${risk?`${risk} ${risk===1?'project needs':'projects need'} attention before the 18:00 UTC delivery window.`:'All projects are projected to meet the 18:00 UTC delivery window.'}</div><span class="badge green">4-HOUR HORIZON</span></div>
<div class="kpis"><div class="card kpi"><div class="kpi-label"><span>Active workers</span><span>♧</span></div><div class="kpi-value">${active}<small>/ 60</small></div><div class="kpi-note"><strong>${state.workers.filter(w=>w.status==='Available').length} on reserve</strong> · ${state.workers.filter(w=>w.status==='Offline').length} offline</div></div><div class="card kpi"><div class="kpi-label"><span>Accepted units today</span><span>▧</span></div><div class="kpi-value">${accepted}<small>/ ${target}</small></div><div class="kpi-note"><strong>${pct(accepted/target*100)} delivered</strong> · acceptance-based</div></div><div class="card kpi"><div class="kpi-label"><span>First-pass acceptance</span><span>◇</span></div><div class="kpi-value">${pct(first*100)}</div><div class="kpi-note">${ms.reduce((n,m)=>n+m.firstReviews,0)} completed first reviews</div></div><div class="card kpi"><div class="kpi-label"><span>Projects at risk</span><span>⚑</span></div><div class="kpi-value">${risk}<small>/ 3</small></div><div class="kpi-note"><span style="color:#b18a55">●</span> Forecast below committed delivery</div></div></div>
<div class="grid"><section class="card"><div class="card-head"><div><h2>Delivery performance</h2><p>Accepted units across all projects · simulated history</p></div><div class="legend"><span><i style="background:#745e93"></i>Accepted</span><span><i style="background:#d7d1df"></i>Target</span></div></div><div class="chart-wrap">${chart()}</div><div class="chart-foot"><span><strong>712 accepted units</strong> in the latest snapshot</span><span>Oct 22 – 28, 2026</span></div></section><section class="card"><div class="card-head"><h2>Delivery watchlist</h2>${badge('Live scenario','gray')}</div>${ms.map(m=>`<div class="risk"><div class="risk-line"><span class="risk-name">${m.name}</span>${badge(m.shortfall?'At risk':'On track',m.shortfall?'amber':'green')}</div><p>${m.client}</p><div class="progress ${m.shortfall?'amber':''}"><span style="width:${Math.min(100,m.forecast/m.target*100)}%"></span></div><div class="risk-bottom"><span>Forecast ${m.forecast} / ${m.target} units</span><button class="text-link" data-project="${m.id}">Investigate ↗</button></div></div>`).join('')}</section></div>
${projectTable(ms)}
<div class="bottom-grid"><section class="card"><div class="card-head"><h2>Operational exceptions</h2><button class="text-link" data-nav="Incidents">View all ↗</button></div>${state.incidents.filter(i=>i.status!=='Resolved').map(i=>`<div class="incident-row"><span class="incident-marker">!</span><div class="incident-copy"><b>${i.title}</b><small>${i.id} · ${projects.find(p=>p.id===i.project).name}</small></div>${badge(i.status,'amber')}</div>`).join('')||'<div class="empty">No open exceptions</div>'}</section><section class="card"><div class="card-head"><h2>Workforce coverage</h2><span class="sub">Assigned vs. required</span></div><div class="capacity">${ms.map(m=>`<div class="capacity-row"><div><span>${m.name}</span><span>${m.active} / 16 agents</span></div><div class="progress"><span style="width:${m.coverage}%"></span></div></div>`).join('')}</div></section></div>`;}
function chart(){const values=[498,565,533,625,589,674,712],targets=[820,860,880,940,960,1000,1040];return `<svg class="chart" viewBox="0 0 650 215" role="img" aria-label="Simulated accepted units by day from October 22 through October 28: 498, 565, 533, 625, 589, 674, 712. Targets: 820, 860, 880, 940, 960, 1000, 1040.">${[0,300,600,900,1200].map(v=>`<line x1="40" x2="640" y1="${183-v*.135}" y2="${183-v*.135}" stroke="#ebe7f0" stroke-dasharray="3 4"/><text x="25" y="${187-v*.135}" font-size="9" fill="#9f96ac" text-anchor="end">${v}</text>`).join('')}${values.map((v,i)=>`<rect x="${58+i*82}" y="${183-targets[i]*.135}" width="48" height="${targets[i]*.135}" fill="#e5dfed" rx="4"/><rect x="${58+i*82}" y="${183-v*.135}" width="48" height="${v*.135}" fill="${i===6?'#453659':'#8c7aa5'}" rx="4"/><text x="${82+i*82}" y="${174-v*.135}" font-size="9" fill="#766987" text-anchor="middle">${v}</text><text x="${82+i*82}" y="205" font-size="9" fill="#988ea6" text-anchor="middle">Oct ${22+i}</text>`).join('')}</svg>`;}
function projectTable(ms){return `<section class="card"><div class="card-head"><div><h2>Project portfolio</h2><p>Client commitments and operational health</p></div><select id="project-filter" aria-label="Filter projects"><option value="all">All projects</option>${projects.map(p=>`<option value="${p.id}" ${filter===p.id?'selected':''}>${p.name}</option>`).join('')}</select></div><div class="table-wrap"><table><thead><tr><th>Project / client</th><th>Workers</th><th>Accepted / target</th><th>First-pass QA</th><th>Delivery status</th><th></th></tr></thead><tbody>${ms.filter(m=>filter==='all'||m.id===filter).map(m=>`<tr><td><div class="project-name"><span class="project-icon" style="color:${m.color}">${m.code}</span><div><b>${m.name}</b><small>${m.client}</small></div></div></td><td>${m.active} <span style="color:#978ea4">/ 16</span></td><td><div class="mini">${m.accepted} <span style="color:#978ea4">/ ${m.target}</span><div class="progress"><span style="width:${m.accepted/m.target*100}%"></span></div></div></td><td>${pct(m.passRate*100)}</td><td>${badge(m.shortfall?'At risk':'On track',m.shortfall?'amber':'green')}</td><td><button class="text-link" data-project="${m.id}" aria-label="Investigate ${m.name}">View ↗</button></td></tr>`).join('')}</tbody></table></div></section>`;}
function workforce(){const ws=state.workers.filter(w=>(workerStatus==='all'||w.status===workerStatus)&&(`${w.name} ${w.id} ${w.region}`.toLowerCase().includes(search.toLowerCase())));return `<div class="filters"><input id="worker-search" aria-label="Search workers" placeholder="Search name, ID or location…" value="${safe(search)}"><select id="worker-status" aria-label="Worker status"><option value="all">All statuses</option>${['Collecting','Available','Offline','Absent'].map(s=>`<option ${s===workerStatus?'selected':''}>${s}</option>`).join('')}</select><button class="btn primary" data-open="P01">Assign reserve worker ↗</button></div><section class="card"><div class="card-head"><h2>Worker directory</h2><span class="sub">${ws.length} of 60 agents</span></div><div class="table-wrap"><table><thead><tr><th>Agent</th><th>Location</th><th>Assignment</th><th>Status</th><th>Qualified projects</th><th>Capacity / h</th></tr></thead><tbody>${ws.map(w=>`<tr><td><div class="project-name"><span class="avatar">${w.name.split(' ').map(n=>n[0]).join('')}</span><div><b>${w.name}</b><small>${w.id}</small></div></div></td><td>${w.region}</td><td>${projects.find(p=>p.id===w.project)?.name||'Reserve pool'}</td><td>${badge(w.status,w.status==='Collecting'?'green':w.status==='Available'?'gray':'amber')}</td><td>${[...new Set(w.qualified)].join(' · ')}</td><td>${w.units} units</td></tr>`).join('')||'<tr><td colspan="6" class="empty">No agents match these filters.</td></tr>'}</tbody></table></div></section><p class="definition">Availability and qualifications are enforced on assignment. Each assignment covers the same 14:00–18:00 UTC window. Capacity is simulated; no real personnel data is used.</p>`;}
function quality(){return `<div class="grid">${totals(state).map(m=>`<section class="card"><div class="card-head"><div><h2>${m.name}</h2><p>${m.client}</p></div>${badge(m.backlog>15?'Review queue':'Stable',m.backlog>15?'amber':'green')}</div><div class="panel-body"><div class="kpi-value">${pct(m.passRate*100)}<small>first-pass</small></div><div class="metric-row"><span>First-pass accepted / reviewed</span><b>${m.firstPass} / ${m.firstReviews}</b></div><div class="metric-row"><span>Awaiting review</span><b>${m.backlog} units</b></div><div class="metric-row"><span>Review capacity</span><b>${m.qaRate+state.extraQA[m.id]} units / h</b></div><div class="metric-row"><span>First-review failures</span><b>${m.firstReviews-m.firstPass} units</b></div><p class="definition">Failures remain in first-pass history after rework. Forecast assumes the observed acceptance ratio continues. Backlog = submitted − reviewed.</p><button class="btn primary" data-qa="${m.id}" ${state.extraQA[m.id]>=12?'disabled':''}>Add reserve QA · +6 units/h</button><p class="definition">$72 per block for the remaining 4 hours · maximum 2 blocks per project</p></div></section>`).join('')}</div><div class="card"><div class="card-head"><h2>QA methodology</h2></div><div class="panel-body"><p>Only accepted work fulfills a delivery commitment. First-pass acceptance uses completed first reviews as its denominator; awaiting-review units are excluded. Rejected and reworked submissions do not create additional accepted units. No client satisfaction scores are invented.</p></div></div>`;}
function incidents(){return `<section class="card"><div class="card-head"><h2>Incident register</h2><span class="sub">${state.incidents.filter(i=>i.status!=='Resolved').length} open exceptions</span></div>${state.incidents.map(i=>`<div class="panel-body" style="border-top:1px solid var(--line);padding-top:20px"><div class="risk-line"><h3>${i.title}</h3>${badge(i.status,i.status==='Resolved'?'green':'amber')}</div><p>${i.detail}</p><div class="risk-line"><span class="sub">${i.id} · ${projects.find(p=>p.id===i.project).name} · Owner: ${i.owner}</span><button class="btn" data-incident="${i.id}">${i.status==='Open'?'Investigate':i.status==='Investigating'?'Resolve incident':'Reopen incident'}</button></div></div>`).join('')}</section><p class="definition">Incident status is a coordination record. Resolving an incident does not restore device connectivity or alter staffing automatically. Scenario capacity changes are controlled separately.</p>`;}
function scenarios(){const ms=totals(state),bs=totals(initialState()),before=bs.reduce((n,m)=>n+m.forecast,0),after=ms.reduce((n,m)=>n+m.forecast,0);return `<div class="details"><section class="card"><div class="card-head"><div><h2>Scenario workbench</h2><p>Same demand. Explicit interventions. Traceable decisions.</p></div>${badge('Simulation','gray')}</div><div class="panel-body"><div class="scenario-control"><div><b>Home routines · connectivity stress</b><p>Reduce collection capacity by 35%. Existing offline agents remain excluded.</p></div><button class="btn ${state.outage?'primary':''}" id="toggle-outage">${state.outage?'Remove stress':'Apply stress'}</button></div><div class="scenario-control"><div><b>Reallocate qualified reserve staff</b><p>Availability, existing assignment and qualification checked before allocation.</p></div><button class="btn" data-open="P01">Review candidates ↗</button></div><div class="scenario-control"><div><b>Retail interactions · QA reserve</b><p>Add 6 reviews/hour at $72 over the four-hour window.</p></div><button class="btn" data-qa="P02" ${state.extraQA.P02>=12?'disabled':''}>Add QA block</button></div><div class="callout">${ms.find(m=>m.id==='P02').limited==='QA capacity'?'Retail delivery is constrained by QA capacity. More collectors cannot resolve that bottleneck alone.':'Retail review capacity has increased. Inspect the forecast to identify the next constraint.'}</div>${resetControls()}<p class="definition">Reset restores baseline staffing, QA, stress and incident statuses; work items and recorded workflow history are retained. This is a deterministic scenario calculation, not a validated prediction model.</p></div></section><section class="card"><div class="card-head"><h2>Baseline vs. current</h2></div><div class="panel-body"><div class="metric-row"><span>Baseline projected accepted units</span><b>${before}</b></div><div class="metric-row"><span>Current projected accepted units</span><b>${after}</b></div><div class="metric-row"><span>Projected output change</span><b>${after-before>=0?'+':''}${after-before} units</b></div><div class="metric-row"><span>Projects at risk</span><b>${bs.filter(m=>m.shortfall).length} → ${ms.filter(m=>m.shortfall).length}</b></div><div class="metric-row"><span>Remaining-window direct cost</span><b>${money(ms.reduce((n,m)=>n+m.cost,0))}</b></div><div class="metric-row"><span>Direct cost change</span><b>${money(ms.reduce((n,m)=>n+m.cost,0)-bs.reduce((n,m)=>n+m.cost,0))}</b></div><p class="definition">Projected accepted = accepted now + min(collection capacity × observed acceptance + eligible backlog, review capacity × observed acceptance). Horizon: 4 hours. Direct cost includes assigned collection labor and incremental QA reserve; existing QA labor and overhead are excluded. This is not profit or realized ROI.</p></div></section></div><section class="card" style="margin-top:24px"><div class="card-head"><h2>Decision audit trail</h2><span class="sub">${state.audit.length} actions</span></div><div class="panel-body">${state.audit.map(a=>`<div class="audit"><small>${new Date(a.time).toLocaleString('en-US',{timeZone:'UTC'})} UTC</small>${safe(a.action)}</div>`).join('')||'<div class="empty">No interventions yet. Apply a scenario or assign a reserve agent to begin.</div>'}</div></section>`;}
function report(){const ms=totals(state);return `<div class="report">${workspaceControls()}<section class="card"><div class="panel-body"><div class="eyebrow">Client operations brief · simulated</div><h2 style="margin-top:14px">Delivery & operational readiness</h2><p class="sub">Snapshot: October 28, 2026, 14:00 UTC · Commitments due at 18:00 UTC</p><p>This report summarizes the current simulated state. ${ms.filter(m=>m.shortfall).length} of 3 client projects are projected below their delivery commitment. Forecasts assume current collection rates and observed QA acceptance continue throughout the remaining four hours.</p>${ms.map(m=>`<div style="border-top:1px solid var(--line);padding-top:20px;margin-top:20px"><div class="risk-line"><h3>${m.client} · ${m.name}</h3>${badge(m.shortfall?'At risk':'On track',m.shortfall?'amber':'green')}</div><ul><li>Accepted delivery: ${m.accepted} of ${m.target} committed units.</li><li>Projected accepted by deadline: ${m.forecast}; projected shortfall: ${m.shortfall}.</li><li>Active collectors: ${m.active}; observed first-pass acceptance: ${pct(m.passRate*100)}.</li><li>Current constraint: ${m.limited.toLowerCase()}; awaiting review: ${m.backlog} units.</li></ul></div>`).join('')}<h3 style="margin-top:24px">Recorded interventions</h3><ul>${state.audit.length?state.audit.map(a=>`<li>${safe(a.action)}</li>`).join(''):'<li>No interventions recorded in this scenario.</li>'}</ul><p class="definition">All workers, clients, costs and operational results are fictional. No real client engagement or achieved business outcome is claimed. Forecast delivery counts accepted units, not uploaded submissions. Browser-local changes are saved on this device only.</p><div class="actions"><button class="btn primary" id="download-report">Download report · CSV ↓</button><button class="btn" id="print-report">Print / save PDF</button></div></div></section></div>`;}
function drawerHTML(){const m=metrics(state,selected),available=state.workers.filter(w=>!eligibility(state,w,selected));return `<div class="modal-bg" id="modal-bg"><section class="drawer" role="dialog" aria-modal="true" aria-labelledby="drawer-title"><button class="close" id="close-drawer" aria-label="Close project details">×</button><div class="eyebrow">Delivery investigation</div><h2 id="drawer-title" style="margin-top:12px">${m.name}</h2><p class="sub" style="margin-top:8px">${m.client} · Deadline 18:00 UTC</p><label class="sr-only" for="drawer-project">Select project</label><select id="drawer-project">${projects.map(p=>`<option value="${p.id}" ${p.id===selected?'selected':''}>${p.name}</option>`).join('')}</select><div class="metric-row"><span>Projected delivery</span><b>${m.forecast} / ${m.target}</b></div><div class="metric-row"><span>Projected shortfall</span><b>${m.shortfall} units</b></div><div class="metric-row"><span>Current constraint</span><b>${m.limited}</b></div><div class="callout">${m.shortfall?`${m.shortfall} accepted units below commitment. Inspect ${m.limited.toLowerCase()} before allocating reserve capacity.`:'Current capacity is projected to cover the commitment. Additional staffing may increase direct cost without improving on-time fulfillment.'}</div><div class="risk-line"><h3>Qualified reserve workers</h3><span class="sub">${available.length} eligible</span></div><p class="definition">Each candidate is available for the same four-hour window, unassigned and qualified. Assignment cost is hourly rate × 4 hours.</p>${available.map(w=>`<div class="candidate"><div><b>${w.name}</b><small>${w.id} · ${w.region} · ${w.units} units/h</small><small>${money(w.hourly)}/h · ${money(w.hourly*4)} window cost</small></div><button class="btn primary" data-assign="${w.id}">Assign</button></div>`).join('')||'<div class="empty">No eligible reserve agents remain.</div>'}<button class="btn" style="width:100%;margin-top:20px" data-qa="${m.id}" ${state.extraQA[m.id]>=12?'disabled':''}>Add QA reserve · +6 units/h · $72</button><p class="definition">Changes are applied to the simulated current scenario and logged. Historical accepted units and first-pass results stay fixed.</p></section></div>`;}
const subtitles={Workflows:'Follow every deliverable from assignment to its final outcome, with the person and changes at each step.',Overview:'Assign workers, monitor quality, and keep client delivery on track.',Workforce:'The right people, ready for the right work.',Quality:'Accepted work is what counts. Keep the review queue moving.',Incidents:'Make exceptions visible. Give every response an owner.',Scenarios:'Explore operational decisions before the delivery window closes.',Reports:'Turn operational complexity into a clear client update.'};
function render(){const scroll=window.scrollY;$('#app').innerHTML=`<aside class="sidebar"><div class="brand"><i>ƒ</i><span>FieldOps</span></div><div class="workspace">OPERATIONS WORKSPACE</div><nav class="nav" aria-label="Main navigation">${Object.keys(icons).map(n=>`<button data-nav="${n}" class="${page===n?'active':''}" aria-label="${n}" ${page===n?'aria-current="page"':''}><svg viewBox="0 0 24 24">${icons[n]}</svg><span>${n}</span>${n==='Incidents'?`<span class="count">${state.incidents.filter(i=>i.status!=='Resolved').length}</span>`:''}</button>`).join('')}</nav><div class="side-bottom"><div class="simulation-note"><b>◈ &nbsp; Portfolio simulation</b>Fictional teams. Real operational constraints. Explore the decisions.</div><div class="profile"><div class="avatar">OM</div><div><b>${safe(state.operatorName)}</b><small>Demo operator · self-declared</small></div></div></div></aside><main class="main"><header class="topbar"><div class="crumb">Workspace <span>/ &nbsp; ${page}</span></div><div class="top-right"><span><i class="live-dot"></i>Simulation environment</span><div class="date">▦ &nbsp; Oct 28, 2026 &nbsp; · &nbsp; 14:00 UTC</div><button class="iconbtn" data-nav="Incidents" aria-label="View operational alerts">♧</button></div></header><div class="content"><div class="eyebrow">STAFFING & OPERATIONS / ${page==='Overview'?'DAILY OPERATIONS':page.toUpperCase()}</div><div class="heading"><div><h1>${page==='Workflows'?'Work & workflow history':page==='Overview'?'Operations overview':page==='Quality'?'Quality assurance':page==='Scenarios'?'Scenario planning':page==='Reports'?'Client reporting':page==='Incidents'?'Incidents & escalations':'Workforce management'}</h1><p class="sub">${subtitles[page]}</p></div><div class="actions"><button class="btn" data-nav="Scenarios">◷ &nbsp; Run a scenario</button><button class="btn primary" data-nav="Reports">Export report &nbsp; ↗</button></div></div>${recoveryBanner()}${({Workflows:()=>workflowView(state,projects,safe,{selectedWork,historyProject,historyActor}),Overview:overview,Workforce:workforce,Quality:quality,Incidents:incidents,Scenarios:scenarios,Reports:report}[page])()}<footer class="footer"><span>FieldOps &nbsp; / &nbsp; Staffing, quality, and delivery — connected.</span><span>Simulated data · USD · UTC · ${storageProblem?'Session only — download backup':'Saved in this browser'}</span></footer></div></main>${drawer?drawerHTML():''}`;bind();window.scrollTo(0,scroll);if(drawer)$('#close-drawer').focus();}
function change(action){const previous=structuredClone(state);try{action();trackOperationalChanges(state,previous);persist();render();}catch(e){state=previous;toast(e.message);}}
function bind(){document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{page=b.dataset.nav;drawer=false;render();window.scrollTo(0,0)});document.querySelectorAll('[data-project],[data-open]').forEach(b=>b.onclick=()=>{selected=b.dataset.project||b.dataset.open;drawer=true;render()});document.querySelectorAll('[data-assign]').forEach(b=>b.onclick=()=>change(()=>{assign(state,b.dataset.assign,selected);toast('Agent assigned. Delivery forecast and cost updated.')}));document.querySelectorAll('[data-qa]').forEach(b=>b.onclick=()=>change(()=>{addQA(state,b.dataset.qa);toast('QA reserve added. Forecast and cost updated.')}));$('#project-filter')?.addEventListener('change',e=>{filter=e.target.value;render()});$('#worker-status')?.addEventListener('change',e=>{workerStatus=e.target.value;render()});$('#worker-search')?.addEventListener('input',e=>{const pos=e.target.selectionStart;search=e.target.value;render();const field=$('#worker-search');field.focus();field.setSelectionRange(pos,pos)});$('#close-drawer')?.addEventListener('click',()=>{drawer=false;render()});$('#modal-bg')?.addEventListener('click',e=>{if(e.target.id==='modal-bg'){drawer=false;render()}});$('#drawer-project')?.addEventListener('change',e=>{selected=e.target.value;render()});$('#toggle-outage')?.addEventListener('click',()=>change(()=>{state.outage=!state.outage;state.audit.unshift({time:new Date().toISOString(),action:`${state.outage?'Applied':'Removed'} 35% connectivity stress to Home routines`})}));$('#reset')?.addEventListener('click',()=>{confirmReset=true;render()});$('#cancel-reset')?.addEventListener('click',()=>{confirmReset=false;render()});$('#confirm-reset')?.addEventListener('click',()=>{const before=structuredClone(state);const baseline=initialState();baseline.workItems=state.workItems;baseline.workflowEvents=state.workflowEvents;baseline.operatorName=state.operatorName;baseline.audit=state.audit;state=baseline;trackOperationalChanges(state,before);state.audit.unshift({time:new Date().toISOString(),action:'Reset staffing scenario; workflow records and prior decisions retained.'});confirmReset=false;persist();render();toast('Demo reset to the original baseline.')});document.querySelectorAll('[data-incident]').forEach(b=>b.onclick=()=>change(()=>{const i=state.incidents.find(i=>i.id===b.dataset.incident);i.status=i.status==='Open'?'Investigating':i.status==='Investigating'?'Resolved':'Open';state.audit.unshift({time:new Date().toISOString(),action:`${i.id}: ${i.status} — ${i.title}`});toast('Incident status updated. Capacity is unchanged.')}));$('#print-report')?.addEventListener('click',()=>window.print());$('#download-report')?.addEventListener('click',downloadReport);bindWorkspace();bindWorkflow();}
function downloadReport(){const rows=[['FieldOps — SIMULATED operational report'],['Snapshot','2026-10-28 14:00 UTC','Horizon','4 hours'],['Project','Client','Accepted','Target','Projected accepted','Shortfall','Active agents','First-pass acceptance','Awaiting QA','Remaining direct cost USD','Constraint'],...totals(state).map(m=>[m.name,m.client,m.accepted,m.target,m.forecast,m.shortfall,m.active,pct(m.passRate*100),m.backlog,m.cost,m.limited]),[],['Intervention time UTC','Action'],...state.audit.map(a=>[a.time,a.action]),[],['Cost excludes existing QA labor and overhead. All data and projections are simulated.']];const csv=rows.map(r=>r.map(csvCell).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='FieldOps-Simulated-Report.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Simulated client report downloaded.');}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&drawer){drawer=false;render()}if(e.key==='Tab'&&drawer){const nodes=[...$('.drawer').querySelectorAll('button:not([disabled]),select')];const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});render();

function bindWorkspace(){
  $('#backup-workspace')?.addEventListener('click',backupWorkspace);
  $('#choose-restore')?.addEventListener('click',()=>$('#restore-file').click());
  $('#restore-file')?.addEventListener('change',async e=>{
    const file=e.target.files[0]; if(!file)return;
    pendingRestore=null;
    try{if(file.size>MAX_BACKUP_BYTES)throw Error('Choose a JSON backup smaller than 2 MB.');pendingRestore=parseBackup(await file.text());render();}
    catch(error){render();$('#restore-error').textContent=error.message;}
    finally{e.target.value='';}
  });
  $('#cancel-restore')?.addEventListener('click',()=>{pendingRestore=null;render()});
  $('#confirm-restore')?.addEventListener('click',()=>{
    if(!pendingRestore)return;
    try{const restored=structuredClone(pendingRestore.state);restored.workflowEvents.push({id:(restored.workflowEvents.at(-1)?.id||0)+1,time:new Date().toISOString(),actor:state.operatorName,entityType:'workspace',entityId:'restore-'+Date.now(),project:null,action:'Workspace restored',note:'Replaced the current local scenario with the selected backup. This is a local recovery operation, not verified history.',before:null,after:{exportedAt:pendingRestore.exportedAt},source:'user'});restored.audit.unshift({time:new Date().toISOString(),action:'Restored workspace from a validated JSON backup (demo history is not verified).'});saveWorkspace(storage,restored);state=restored;storageProblem=null;damagedRaw=null;pendingRestore=null;render();toast('Workspace restored and saved in this browser.');}
    catch{toast('Restore could not be saved. Your current workspace is unchanged. Download a backup and check browser storage.');}
  });
  $('#download-damaged')?.addEventListener('click',()=>downloadText(damagedRaw,'FieldOps-Preserved-Saved-Data.txt','text/plain'));
  $('#replace-damaged')?.addEventListener('click',()=>{page='Reports';pendingRestore={state:structuredClone(state),exportedAt:new Date().toISOString()};render()});
}

function bindWorkflow(){
 document.querySelectorAll('[data-work]').forEach(b=>b.onclick=()=>{selectedWork=b.dataset.work;render()});
 $('#save-operator')?.addEventListener('click',()=>change(()=>{const name=$('#operator-name').value.trim();if(!name||name.length>80)throw Error('Enter an operator name of 1–80 characters.');state.operatorName=name;toast('Operator name set. Earlier records retain their original names.')}));
 $('#new-work-form')?.addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.target);change(()=>{selectedWork=createWork(state,{title:data.get('title'),project:data.get('project'),owner:data.get('owner')},data.get('note'));toast('Work item created with its assignment history.');})});
 $('#advance-work-form')?.addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.target);change(()=>{advanceWork(state,selectedWork,data.get('next'),data.get('note'),data.get('output'));toast('Workflow step recorded with operator and before/after values.');})});
 $('#history-project')?.addEventListener('change',e=>{historyProject=e.target.value;render()});
 $('#history-actor')?.addEventListener('change',e=>{historyActor=e.target.value;render()});
 $('#download-workflow')?.addEventListener('click',()=>{const rows=[['FieldOps workflow history — SIMULATED; operator names are self-declared'],['Sequence','Time UTC','Operator','Entity type','Record','Project','Action','Note','Before','After','Source'],...state.workflowEvents.map(e=>[e.id,e.time,e.actor,e.entityType,e.entityId,e.project||'',e.action,e.note,JSON.stringify(e.before),JSON.stringify(e.after),e.source])];downloadText(rows.map(row=>row.map(csvCell).join(',')).join('\r\n'),'FieldOps-Workflow-History.csv','text/csv;charset=utf-8');toast('Complete workflow history exported.');});
}
